<?php
namespace App\Services;use App\Models\{TransportService,TransportSetting};
class TransportEvidenceService {public function evaluate(TransportService$s):array{$missing=[];if(!$s->actual_start_at)$missing[]='Salida';if(!$s->actual_arrival_at)$missing[]='Llegada';$requires=TransportSetting::where('company_id',$s->company_id)->value('requires_arrival_signature');$hasSignature=$s->relationLoaded('arrivalSignature')?(bool)$s->arrivalSignature:$s->arrivalSignature()->exists();if($requires&&!$hasSignature)$missing[]='Firma de llegada';$hasOpenIssues=$s->relationLoaded('issues')?$s->issues->contains('status','open'):$s->issues()->where('status','open')->exists();if($hasOpenIssues)$missing[]='Novedad abierta';if($s->status!=='closed')$missing[]='Cierre';$status=count($missing)===0?'complete':(count($missing)>=4?'missing':'partial');return compact('status','missing');}}
